void setup() {
  pinMode(2, OUTPUT);     // GPIO 2 becomes an output
}

void loop() {
  digitalWrite(2, HIGH);  // LED on
  delay(500);             // wait half a second
  digitalWrite(2, LOW);   // LED off
  delay(500);
}

